export function AchievementGrid(e){return`\n        <div class="achievement-grid">\n            ${e.map(e=>`\n        <div class="achievement-card">\n            <div class="achievement-badge">${e.category}</div>\n            <h4>${e.title}</h4>\n            <p>${e.description}</p>\n            <span class="achievement-year">${e.year}</span>\n        </div>\n    `).join("")}\n        </div>\n    `}